// PREIMAGE-SHA-256 crypto-conditions (RFC draft-thomas-crypto-conditions), DER-encoded by hand.
// Pure functions: no network, no persistence. Conditions are generated by core's release service (CORE-12) and
// handed to closeLoanAndCreateEscrows; this package only validates/encodes them and checks fulfillments.
import { createHash, timingSafeEqual } from "node:crypto";

/** Encode a fulfillment for a raw preimage: A0 len 80 len <preimage>. */
export function fulfillmentFromPreimage(preimage: Uint8Array): string {
  if (preimage.length > 127) throw new Error("preimage too long for short-form DER");
  const inner = Buffer.concat([Buffer.from([0x80, preimage.length]), Buffer.from(preimage)]);
  return Buffer.concat([Buffer.from([0xa0, inner.length]), inner]).toString("hex").toUpperCase();
}

/** Encode the condition for a preimage: A0 25 80 20 <sha256> 81 01 <cost=len>. */
export function conditionFromPreimage(preimage: Uint8Array): string {
  if (preimage.length > 127) throw new Error("preimage too long");
  const fp = createHash("sha256").update(preimage).digest();
  const inner = Buffer.concat([Buffer.from([0x80, 0x20]), fp, Buffer.from([0x81, 0x01, preimage.length])]);
  return Buffer.concat([Buffer.from([0xa0, inner.length]), inner]).toString("hex").toUpperCase();
}

/** Extract the preimage from a PREIMAGE-SHA-256 fulfillment hex. */
export function preimageFromFulfillment(fulfillmentHex: string): Buffer {
  const b = Buffer.from(fulfillmentHex, "hex");
  if (b[0] !== 0xa0 || b[2] !== 0x80) throw new Error("not a PREIMAGE-SHA-256 fulfillment");
  const len = b[3]!;
  if (b[1] !== len + 2 || b.length !== len + 4) throw new Error("malformed fulfillment length");
  return b.subarray(4, 4 + len);
}

/** True iff `fulfillment` satisfies `condition`. Check before submitting EscrowFinish. */
export function fulfillmentMatches(condition: string, fulfillment: string): boolean {
  try {
    const expected = Buffer.from(conditionFromPreimage(preimageFromFulfillment(fulfillment)), "hex");
    const actual = Buffer.from(condition, "hex");
    return expected.length === actual.length && timingSafeEqual(expected, actual);
  } catch {
    return false;
  }
}

/** PREIMAGE-SHA-256 condition for a 32-byte preimage: `A0258020` + sha256 (64 hex) + `810120` = 78 hex chars. */
export const PREIMAGE_CONDITION_RE = /^A0258020[0-9A-F]{64}810120$/;

/** Uppercase a hex condition (rippled reports blobs uppercase), so equality/duplicate checks are case-insensitive. */
export function normalizeCondition(condition: string): string {
  return condition.trim().toUpperCase();
}

/** True iff `condition` is a PREIMAGE-SHA-256 condition for a 32-byte preimage (case-insensitive hex). */
export function isPreimageSha256Condition(condition: string): boolean {
  return PREIMAGE_CONDITION_RE.test(normalizeCondition(condition));
}

/** DER prefixes that are safe to name in an error: a condition's and a fulfillment's (the secret starts after them). */
const KNOWN_DER_PREFIXES = new Set(["A0258020", "A0228020"]);

/**
 * Describe a value that should have been a condition WITHOUT echoing it (security review M2): callers mix up condition
 * and fulfillment (both hex from the release service), and a fulfillment or raw preimage in an error message ends up
 * in HTTP responses and logs.
 */
export function describeConditionInput(raw: unknown): string {
  if (typeof raw !== "string") return `a ${raw === null ? "null" : typeof raw}`;
  const s = raw.trim();
  if (/^A0228020[0-9A-F]{64}$/i.test(s)) return "a PREIMAGE-SHA-256 FULFILLMENT, which is the secret (value not echoed): pass its condition";
  if (/^[0-9A-F]{64}$/i.test(s)) return "64 hex chars, a raw preimage or a hash (value not echoed)";
  const prefix = s.slice(0, 8).toUpperCase();
  return `${s.length} chars${KNOWN_DER_PREFIXES.has(prefix) ? `, starting ${prefix}` : ""} (value not echoed)`;
}

/** Throws unless `condition` is a 32-byte PREIMAGE-SHA-256 condition. Returns it normalized (uppercase). */
export function assertPreimageSha256Condition(condition: string, label = "condition"): string {
  const c = normalizeCondition(condition);
  if (!PREIMAGE_CONDITION_RE.test(c)) {
    throw new Error(`${label}: not a 32-byte PREIMAGE-SHA-256 condition (want A0258020<64 hex>810120, 78 hex chars); got ${describeConditionInput(condition)}`);
  }
  return c;
}
